const express = require('express');
const router = express.Router();
const { createClient } = require('@supabase/supabase-js');
const supabase = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_SERVICE_KEY);

router.get('/stats', async (req, res) => {
  try {
    const token = req.headers.authorization?.split(' ')[1];
    const { data: { user } } = await supabase.auth.getUser(token);
    if (!user) return res.status(401).json({ error: 'Unauthorized' });

    const today = new Date().toISOString().split('T')[0];
    const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
    const monthAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString();

    // Total generated (all time)
    const { count: totalGenerated } = await supabase
      .from('generated_outputs')
      .select('*', { count: 'exact' })
      .eq('user_id', user.id);

    // Generated this month
    const { count: generatedThisMonth } = await supabase
      .from('generated_outputs')
      .select('*', { count: 'exact' })
      .eq('user_id', user.id)
      .gte('created_at', monthAgo);

    // Followers count
    const { count: followersCount } = await supabase
      .from('followers')
      .select('*', { count: 'exact' })
      .eq('following_id', user.id);

    // Stars earned this week
    const { data: weekStars } = await supabase
      .from('stars')
      .select('amount, type')
      .eq('user_id', user.id)
      .gte('created_at', weekAgo);

    const starsThisWeek = weekStars?.reduce((acc, s) => {
      if (s.type === 'earned' || s.type === 'received') return acc + s.amount;
      return acc;
    }, 0) || 0;

    // Total stars all time
    const { data: allStars } = await supabase
      .from('stars')
      .select('amount, type')
      .eq('user_id', user.id);

    const totalStars = allStars?.reduce((acc, s) => {
      if (s.type === 'earned' || s.type === 'received') return acc + s.amount;
      if (s.type === 'spent' || s.type === 'gifted') return acc - s.amount;
      return acc;
    }, 0) || 0;

    // Generations today
    const { count: todayCount } = await supabase
      .from('content_inputs')
      .select('*', { count: 'exact' })
      .eq('user_id', user.id)
      .gte('created_at', today);

    // Recent activity (last 5 generations)
    const { data: recentActivity } = await supabase
      .from('generated_outputs')
      .select('id, output_type, created_at, content')
      .eq('user_id', user.id)
      .order('created_at', { ascending: false })
      .limit(5);

    res.json({
      totalGenerated: totalGenerated || 0,
      generatedThisMonth: generatedThisMonth || 0,
      followersCount: followersCount || 0,
      starsThisWeek,
      totalStars,
      todayCount: todayCount || 0,
      dailyLimit: 5,
      recentActivity: recentActivity || []
    });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

module.exports = router;
